import React, { useState } from 'react';
import { Facebook, Instagram } from 'lucide-react';
import './BoubaayaFooter.css';

export default function BoubaayaFooter() {
  const [email, setEmail] = useState('');

  const handleSubmit = () => {
    if (email && email.includes('@')) {
      console.log('Newsletter subscription:', email);
      alert('Merci pour votre inscription!');
      setEmail('');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSubmit();
    }
  };

  return (
    <div className="footer-container">
      <div className="footer-wrapper">
        <div className="footer-grid">
          {/* Brand Section */}
          <div>
            <h2 className="brand-title">Boubaaya</h2>
            <p className="brand-description">
              Vêtements féminins élégants pour la femme algérienne moderne.
            </p>
            <div className="social-links">
              <a href="#" className="social-link" aria-label="Facebook">
                <Facebook size={20} />
              </a>
              <a href="#" className="social-link" aria-label="Instagram">
                <Instagram size={20} />
              </a>
            </div>
          </div>

          {/* Navigation Section */}
          <div>
            <h3 className="section-title">Navigation</h3>
            <ul className="nav-list">
              <li><a href="#" className="nav-link">Accueil</a></li>
              <li><a href="#" className="nav-link">Catégories</a></li>
              <li><a href="#" className="nav-link">Produits</a></li>
              <li><a href="#" className="nav-link">Inspiration</a></li>
            </ul>
          </div>

          {/* Contact Section */}
          <div>
            <h3 className="section-title">Contact</h3>
            <ul className="contact-list">
              <li>
                Email: <a href="mailto:contact@boubaaya.dz" className="contact-link">contact@boubaaya.dz</a>
              </li>
              <li>
                Tél: <a href="tel:+213XXXXXXXXX" className="contact-link">+213 XXX XXX XXX</a>
              </li>
              <li>Alger, Algérie</li>
            </ul>
          </div>

          {/* Newsletter Section */}
          <div>
            <h3 className="section-title">Newsletter</h3>
            <p className="newsletter-description">
              Inscrivez-vous pour recevoir nos dernières nouveautés
            </p>
            <div className="newsletter-form">
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder="Votre email"
                className="newsletter-input"
              />
              <button onClick={handleSubmit} className="newsletter-button">
                →
              </button>
            </div>
          </div>
        </div>

        {/* Bottom Bar */}
        <div className="footer-bottom">
          <p className="copyright">© 2025 Boubaaya. Tous droits réservés.</p>
          <p className="activate-windows">Activate Windows</p>
        </div>
      </div>
    </div>
  );
}
